import "core-js/modules/es.array.push.js";
/* eslint-disable */
import { getS3SignedUrl } from "@/mixins/S3GetStorageFile.js";
export default {
  props: {
    mediaView: Boolean,
    entryInfo: Object
  },
  data() {
    return {
      mediaAttachments: []
    };
  },
  watch: {
    mediaView: {
      async handler() {
        if (this.mediaView == true) {
          this.mediaAttachments = [];
          for (let i = 0; i < this.entryInfo.attachments_keys.length; i++) {
            let details = this.$store.getters.GetOrgDetails;
            let signedUrl = await getS3SignedUrl(this.entryInfo.attachments_keys[i], details.s3_details);
            if (signedUrl) {
              this.mediaAttachments.push(signedUrl);
            }
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    }
  }
};
